<%_
const rootVars = (typeof variables === 'object' && variables) ? variables : {};
const stat = rootVars.stat_data || rootVars;
const get = (path, fallback = '') => (typeof _ !== 'undefined' && _.get) ? _.get(stat, path, fallback) : fallback;
const ownKeys = value => (value && typeof value === 'object' && !Array.isArray(value)) ? Object.keys(value) : [];
const pickKeys = (path, limit = 8) => ownKeys(get(path, {})).slice(0, limit);
const count = path => ownKeys(get(path, {})).length;
const firstRecordNames = (path, limit = 5) => pickKeys(path, limit);
const currentCharRequired = ['年龄','身份','与user的关系','自我认知','心声','三围','好感度','堕落值','服从度','外貌描写','颜值评分','当前状态'];
const currentCharNestedRequired = {
  衣着: ['上装','下装','内衣','内裤','袜子','鞋子','配饰'],
  身体状态: ['朱唇','乳房','美臀','小穴','菊穴','玉足'],
  细节档案: ['天赋','技能','习惯','癖好','携带物','宿舍房间'],
  私密档案: ['是否为处女','初夜对象','名器','名器活跃度','纹身']
};
const isMissingValue = value => value === undefined || value === null || value === '';
const currentCharMissingFields = value => {
  const obj = (value && typeof value === 'object' && !Array.isArray(value)) ? value : {};
  const missing = [];
  currentCharRequired.forEach(key => { if (isMissingValue(obj[key])) missing.push(key); });
  Object.entries(currentCharNestedRequired).forEach(([group, keys]) => {
    const nested = (obj[group] && typeof obj[group] === 'object' && !Array.isArray(obj[group])) ? obj[group] : {};
    if (!obj[group] || typeof obj[group] !== 'object' || Array.isArray(obj[group])) {
      missing.push(group);
      return;
    }
    keys.forEach(key => { if (isMissingValue(nested[key])) missing.push(group + '.' + key); });
  });
  return missing;
};
const currentCharCompleteness = (charPath, limit = 6) => Object.fromEntries(firstRecordNames(charPath, limit).map(name => {
  const missing = currentCharMissingFields(get(`${charPath}.${name}`, {}));
  const total = currentCharRequired.length + Object.values(currentCharNestedRequired).reduce((sum, keys) => sum + keys.length, 0);
  return [name, { 完整度: String(total - missing.length) + '/' + String(total), 缺失字段: missing.slice(0, 24) }];
}));
const compact = value => {
  if (value === undefined || value === null || value === '') return '未记录';
  if (Array.isArray(value)) return value.length ? value.slice(0, 6).join('、') : '未记录';
  if (typeof value === 'object') {
    const keys = Object.keys(value);
    return keys.length ? keys.slice(0, 8).join('、') : '未记录';
  }
  return String(value);
};
const summary = {
  说明: '本段由 EJS 在生成时读取当前变量后自动压缩；不要把完整 stat_data 逐字复述，只按摘要判断剧情和变量更新。',
  环境: {
    日期: compact(get('环境.日期')),
    时间: compact(get('环境.时间')),
    经过天数: compact(get('环境.经过天数')),
    所在位置: compact(get('环境.所在位置')),
    近期节日: compact(get('环境.近期节日')),
    空间环境: {
      位置类型: compact(get('环境.空间环境.位置类型')),
      环境描述: compact(get('环境.空间环境.环境描述')),
      重力水平: compact(get('环境.空间环境.重力水平')),
      光照条件: compact(get('环境.空间环境.光照条件')),
      环境表面温度: compact(get('环境.空间环境.环境表面温度')),
      环境气压: compact(get('环境.空间环境.环境气压')),
      辐射剂量率: compact(get('环境.空间环境.辐射剂量率')),
      磁场强度: compact(get('环境.空间环境.磁场强度')),
      太阳活动: compact(get('环境.空间环境.太阳活动')),
      太阳风速度: compact(get('环境.空间环境.太阳风速度')),
      太阳辐射通量: compact(get('环境.空间环境.太阳辐射通量')),
      微流星体风险: compact(get('环境.空间环境.微流星体风险')),
      机体承受G力: compact(get('环境.空间环境.机体承受G力')),
      人体承受G力: compact(get('环境.空间环境.人体承受G力')),
      宇航服内温度: compact(get('环境.空间环境.宇航服内温度')),
      宇航服内湿度: compact(get('环境.空间环境.宇航服内湿度')),
      宇航服内压力: compact(get('环境.空间环境.宇航服内压力')),
      大气成分: compact(get('环境.空间环境.大气成分'))
    }
  },
  自身: {
    身份: compact(get('user.身份背景.身份')),
    背景: compact(get('user.身份背景.背景')),
    当前穿着: compact(get('user.当前穿着')),
    等级: compact(get('user.基本属性.等级')),
    EXP进度: compact(get('user.基本属性.EXP进度')),
    精神韧性: compact(get('user.基本属性.精神韧性')),
    核心属性: get('user.核心属性', {}),
    体质值: compact(get('user.体质值')),
    体力: compact(get('user.体力')),
    饱腹值: compact(get('user.饱腹值')),
    水分值: compact(get('user.水分值')),
    洁净值: compact(get('user.洁净值')),
    信用点: compact(get('user.信用点')),
    房间: firstRecordNames('user.房间', 5),
    成就数: Array.isArray(get('user.成就', [])) ? get('user.成就', []).length : 0
  },
  动态容器数量: {
    持有物: count('持有物'),
    仓库: count('仓库'),
    机体信息: count('机体信息'),
    雷达系统: count('雷达系统'),
    当前互动角色: count('当前互动角色'),
    关系网: count('关系网'),
    队伍角色: count('队伍角色'),
    道具放置列表: count('道具放置列表'),
    商贸已知货物: count('商贸已知货物'),
    基地与资源: count('基地与资源'),
    任务: count('任务'),
    母舰: count('母舰')
  },
  服从概览: {
    当前互动角色: Object.fromEntries(firstRecordNames('当前互动角色', 6).map(name => [name, compact(get(`当前互动角色.${name}.服从度`))])),
    关系网: Object.fromEntries(firstRecordNames('关系网', 6).map(name => [name, compact(get(`关系网.${name}.服从度`))])),
    队伍角色: Object.fromEntries(firstRecordNames('队伍角色', 6).map(name => [name, compact(get(`队伍角色.${name}.服从度`))]))
  },
  当前互动角色字段完整度: currentCharCompleteness('当前互动角色', 6),
  当前重点条目: {
    互动角色: firstRecordNames('当前互动角色', 6),
    队伍角色: firstRecordNames('队伍角色', 6),
    关系网: firstRecordNames('关系网', 6),
    机体: firstRecordNames('机体信息', 6),
    任务: firstRecordNames('任务', 6),
    持有物: firstRecordNames('持有物', 8),
    世界变化: firstRecordNames('规则变化.世界变化', 6)
  }
};
print('<VariableStateSummary>');
print(JSON.stringify(summary, null, 2));
print('</VariableStateSummary>');
_%>

